typedef unsigned int u_int;
typedef unsigned long long u_long;
typedef unsigned long long u_long128;

struct QWORD
{
    u_long l[2];
};

struct TimeStamp;

struct ViBuf
{
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    char env[36];
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
};

extern "C" int WaitSema(int);
extern "C" int SignalSema(int);
extern void nvlPrintf(const char *, ...);
static int getFIFOindex(ViBuf *, void *);
static void setD4_CHCR(u_int);
static void scTag2(QWORD *, void *, u_int, u_int);

#define VIBUF_ELM_SIZE 2048
#define DMA_ID_REFE 0
#define DMA_ID_REF 3
#define D4_CHCR ((volatile u_int *)0x1000C000)
#define D4_MADR ((volatile u_int *)0x1000C010)
#define false 0
#define TRUE 1

static int viBufAddDMA( ViBuf* f )
{
    int i, index, id, last, isNewData = 0, consume, read_start, read_n;
    u_int   d4chcr;

    WaitSema(f->sema);
    if( !f->isActive )
    {
        nvlPrintf( "DMA ADD not active\n" );
        SignalSema( f->sema );
        return false;
    }

    ///////////////////////////////////////////
    // STOP DMA ch4
    //
    // d4chcr:
    //	(1) DMA was running
    //	    ORIGINAL DMA tag
    //	(2) DMA was not running
    //	    REFE tag
    setD4_CHCR( (DMA_ID_REFE<<28) | (0<<8) | (1<<2) | 1 );
    d4chcr = *D4_CHCR;
    // update dma pointer using D4_MADR
    index = getFIFOindex( f, (void*)*D4_MADR );
    consume = ( index + f->n - f->dmaStart ) % f->n;
    f->dmaStart = ( f->dmaStart + consume ) % f->n;
    f->dmaN -= consume;
    // update read pointer
    read_start = ( f->dmaStart + f->dmaN ) % f->n;
    read_n = f->readBytes / VIBUF_ELM_SIZE;
    f->readBytes %= VIBUF_ELM_SIZE;
    // the last REFE -> REF
    if( read_n > 0 )
    {
        last = ( f->dmaStart + f->dmaN - 1 + f->n ) % f->n;
        scTag2( (QWORD*)(f->tag + last), (char*)f->data + VIBUF_ELM_SIZE * last, DMA_ID_REF, VIBUF_ELM_SIZE / 16 );
        isNewData = 1;
    }
    index = read_start;
    for( i = 0; i < read_n; i++ )
    {
        id = (i == read_n - 1)? DMA_ID_REFE: DMA_ID_REF;
        scTag2( (QWORD*)(f->tag + index), (char*)f->data + VIBUF_ELM_SIZE * index, id, VIBUF_ELM_SIZE / 16 );
        index = ( index + 1 ) % f->n;
    }
    f->dmaN += read_n;
    // RESTART DMA ch4
    if( f->dmaN )
    {
        if( isNewData )
        {
            // change ref/refe ----> ref
            d4chcr = (d4chcr & 0x0fffffff) | (DMA_ID_REF << 28);
        }
        setD4_CHCR(d4chcr | 0x100);
    }
    SignalSema(f->sema);
    return TRUE;
}
